[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>SnapFrame — Capture, Create & Share What You Love</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --black: #000000;
      --purple: #7638FA;
      --orange: #FF7A00;
      --magenta: #D946EF;
      --white: #FFFFFF;
      --gray-50: #F9FAFB;
      --gray-100: #F3F4F6;
      --gray-200: #E5E7EB;
      --gray-300: #D1D5DB;
      --gray-400: #9CA3AF;
      --gray-500: #6B7280;
      --gray-600: #4B5563;
      --gray-700: #374151;
      --gray-800: #1F2937;
      --gray-900: #111827;
      --gradient-brand: linear-gradient(135deg, var(--purple) 0%, var(--magenta) 50%, var(--orange) 100%);
      --gradient-hero: linear-gradient(135deg, #7638FA 0%, #C026D3 40%, #FF7A00 100%);
      --font: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --radius-full: 9999px;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
      --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.04);
      --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.08), 0 8px 10px -6px rgba(0,0,0,0.04);
      --max-width: 1200px;
      --transition: 200ms ease;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font);
      color: var(--gray-900);
      background: var(--white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    a { text-decoration: none; color: inherit; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }
    img { max-width: 100%; display: block; }

    /* ===== HEADER ===== */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 100;
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--gray-200);
      transition: background var(--transition);
    }

    .header-inner {
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 0 24px;
      height: 64px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .logo {
      font-size: 22px;
      font-weight: 800;
      letter-spacing: -0.5px;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .logo-icon {
      width: 32px;
      height: 32px;
      border-radius: var(--radius-sm);
      background: var(--gradient-brand);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg {
      width: 18px;
      height: 18px;
      color: white;
    }

    .header-actions {
      display: flex;
      align-items: center;
      gap: 16px;
    }

    .btn-login {
      padding: 8px 20px;
      font-size: 14px;
      font-weight: 600;
      color: var(--gray-900);
      border: 1.5px solid var(--gray-300);
      border-radius: var(--radius-full);
      transition: all var(--transition);
    }

    .btn-login:hover {
      border-color: var(--gray-900);
      background: var(--gray-900);
      color: var(--white);
    }

    .hamburger {
      display: none;
      width: 44px;
      height: 44px;
      align-items: center;
      justify-content: center;
      border-radius: var(--radius-sm);
      transition: background var(--transition);
    }

    .hamburger:hover { background: var(--gray-100); }

    .hamburger-icon {
      width: 22px;
      height: 16px;
      position: relative;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
    }

    .hamburger-icon span {
      display: block;
      width: 100%;
      height: 2px;
      background: var(--gray-900);
      border-radius: 2px;
      transition: all 250ms ease;
      transform-origin: center;
    }

    .hamburger.active .hamburger-icon span:nth-child(1) {
      transform: translateY(7px) rotate(45deg);
    }
    .hamburger.active .hamburger-icon span:nth-child(2) {
      opacity: 0;
    }
    .hamburger.active .hamburger-icon span:nth-child(3) {
      transform: translateY(-7px) rotate(-45deg);
    }

    /* Mobile nav */
    .mobile-nav {
      display: none;
      position: fixed;
      top: 64px;
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--white);
      z-index: 99;
      padding: 24px;
      opacity: 0;
      transform: translateY(-8px);
      transition: opacity 250ms ease, transform 250ms ease;
      pointer-events: none;
    }

    .mobile-nav.open {
      opacity: 1;
      transform: translateY(0);
      pointer-events: all;
    }

    .mobile-nav-links {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 4px;
    }

    .mobile-nav-links a {
      display: block;
      padding: 14px 16px;
      font-size: 18px;
      font-weight: 600;
      color: var(--gray-900);
      border-radius: var(--radius-md);
      transition: background var(--transition);
    }

    .mobile-nav-links a:hover { background: var(--gray-100); }

    .mobile-nav .btn-login-mobile {
      display: block;
      margin-top: 24px;
      padding: 14px;
      text-align: center;
      font-size: 16px;
      font-weight: 600;
      color: var(--white);
      background: var(--gray-900);
      border-radius: var(--radius-full);
      transition: opacity var(--transition);
    }

    .mobile-nav .btn-login-mobile:hover { opacity: 0.85; }

    /* ===== HERO ===== */
    .hero {
      padding: 160px 24px 100px;
      text-align: center;
      position: relative;
      overflow: hidden;
      background: var(--gray-50);
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -200px;
      right: -200px;
      width: 600px;
      height: 600px;
      border-radius: 50%;
      background: radial-gradient(circle, rgba(118,56,250,0.12) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero::after {
      content: '';
      position: absolute;
      bottom: -150px;
      left: -150px;
      width: 500px;
      height: 500px;
      border-radius: 50%;
      background: radial-gradient(circle, rgba(255,122,0,0.1) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero-inner {
      max-width: 800px;
      margin: 0 auto;
      position: relative;
      z-index: 1;
    }

    .hero h1 {
      font-size: clamp(36px, 5vw, 64px);
      font-weight: 800;
      line-height: 1.1;
      letter-spacing: -1.5px;
      margin-bottom: 32px;
      color: var(--gray-900);
    }

    .hero h1 .gradient-text {
      background: var(--gradient-hero);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .btn-primary {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 16px 36px;
      font-size: 16px;
      font-weight: 700;
      color: var(--white);
      background: var(--gradient-brand);
      border-radius: var(--radius-full);
      transition: transform var(--transition), box-shadow var(--transition);
      box-shadow: 0 4px 15px rgba(118,56,250,0.3);
    }

    .btn-primary:hover {
      transform: translateY(-2px);
      box-shadow: 0 8px 25px rgba(118,56,250,0.4);
    }

    .btn-primary:active { transform: translateY(0); }

    .btn-primary svg {
      width: 18px;
      height: 18px;
    }

    /* ===== SECTION LAYOUT ===== */
    .section {
      padding: 96px 24px;
    }

    .section-inner {
      max-width: var(--max-width);
      margin: 0 auto;
    }

    /* ===== FEATURES ===== */
    .features {
      background: var(--white);
    }

    .content-card {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      align-items: center;
    }

    .content-card-text h2 {
      font-size: clamp(28px, 3.5vw, 42px);
      font-weight: 800;
      line-height: 1.15;
      letter-spacing: -0.8px;
      margin-bottom: 20px;
    }

    .content-card-text p {
      font-size: 17px;
      line-height: 1.7;
      color: var(--gray-600);
      margin-bottom: 28px;
    }

    .section-link {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 16px;
      font-weight: 700;
      color: var(--purple);
      transition: gap var(--transition);
    }

    .section-link:hover { gap: 10px; }

    .section-link svg {
      width: 18px;
      height: 18px;
    }

    .content-card-visual {
      position: relative;
      border-radius: var(--radius-xl);
      overflow: hidden;
      aspect-ratio: 4/3;
    }

    .visual-placeholder {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 48px;
      font-weight: 800;
      color: rgba(255,255,255,0.3);
    }

    .features .content-card-visual {
      background: linear-gradient(135deg, #7638FA 0%, #A855F7 50%, #D946EF 100%);
    }

    .features .visual-placeholder::before {
      content: '';
      position: absolute;
      width: 180px;
      height: 180px;
      border-radius: 50%;
      background: rgba(255,255,255,0.08);
      top: 20%;
      right: 15%;
    }

    .features .visual-placeholder::after {
      content: '';
      position: absolute;
      width: 120px;
      height: 120px;
      border-radius: var(--radius-lg);
      background: rgba(255,255,255,0.06);
      bottom: 15%;
      left: 10%;
      transform: rotate(15deg);
    }

    /* ===== SAFETY ===== */
    .safety {
      background: var(--gray-50);
    }

    .safety .content-card {
      direction: rtl;
    }

    .safety .content-card > * {
      direction: ltr;
    }

    .safety .content-card-visual {
      background: linear-gradient(135deg, #06B6D4 0%, #3B82F6 50%, #6366F1 100%);
    }

    .safety .section-link {
      color: #3B82F6;
    }

    .safety .visual-placeholder::before {
      content: '';
      position: absolute;
      width: 100px;
      height: 100px;
      border: 3px solid rgba(255,255,255,0.15);
      border-radius: 50%;
      top: 25%;
      left: 20%;
    }

    .safety .visual-placeholder::after {
      content: '';
      position: absolute;
      width: 60px;
      height: 60px;
      background: rgba(255,255,255,0.1);
      border-radius: 50%;
      top: 30%;
      left: 25%;
    }

    /* ===== CREATORS ===== */
    .creators {
      background: var(--white);
    }

    .creators .content-card-visual {
      background: linear-gradient(135deg, #F97316 0%, #FB923C 40%, #FBBF24 100%);
    }

    .creators .section-link {
      color: var(--orange);
    }

    .creators .visual-placeholder::before {
      content: '';
      position: absolute;
      width: 200px;
      height: 200px;
      border-radius: 40%;
      background: rgba(255,255,255,0.08);
      top: 10%;
      right: 5%;
      transform: rotate(25deg);
    }

    /* ===== TAGLINE BANNER ===== */
    .tagline-banner {
      padding: 80px 24px;
      background: var(--gradient-brand);
      text-align: center;
      position: relative;
      overflow: hidden;
    }

    .tagline-banner::before {
      content: '';
      position: absolute;
      top: -100px;
      left: -100px;
      width: 300px;
      height: 300px;
      border-radius: 50%;
      background: rgba(255,255,255,0.06);
      pointer-events: none;
    }

    .tagline-banner::after {
      content: '';
      position: absolute;
      bottom: -80px;
      right: -80px;
      width: 250px;
      height: 250px;
      border-radius: 50%;
      background: rgba(255,255,255,0.05);
      pointer-events: none;
    }

    .tagline-banner h2 {
      font-size: clamp(28px, 4vw, 48px);
      font-weight: 800;
      color: var(--white);
      letter-spacing: -1px;
      position: relative;
      z-index: 1;
      max-width: 700px;
      margin: 0 auto;
    }

    /* ===== NEWS ===== */
    .news {
      background: var(--gray-50);
      padding: 96px 0;
    }

    .news-header {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      margin-bottom: 48px;
      padding: 0 24px;
      max-width: var(--max-width);
      margin-left: auto;
      margin-right: auto;
    }

    .news-label {
      font-size: 13px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1.5px;
      color: var(--purple);
      margin-bottom: 8px;
    }

    .news-header h2 {
      font-size: clamp(28px, 3.5vw, 40px);
      font-weight: 800;
      letter-spacing: -0.8px;
    }

    .news-view-more {
      font-size: 15px;
      font-weight: 700;
      color: var(--purple);
      white-space: nowrap;
      display: inline-flex;
      align-items: center;
      gap: 6px;
      transition: gap var(--transition);
    }

    .news-view-more:hover { gap: 10px; }

    .news-view-more svg {
      width: 16px;
      height: 16px;
    }

    .news-carousel-wrapper {
      position: relative;
    }

    .news-carousel {
      display: flex;
      gap: 24px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      padding: 0 24px 16px;
      scrollbar-width: none;
      -ms-overflow-style: none;
    }

    .news-carousel::-webkit-scrollbar { display: none; }

    .news-card {
      flex: 0 0 340px;
      scroll-snap-align: start;
      background: var(--white);
      border-radius: var(--radius-xl);
      overflow: hidden;
      box-shadow: var(--shadow-md);
      transition: transform var(--transition), box-shadow var(--transition);
      cursor: pointer;
    }

    .news-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-xl);
    }

    .news-card-thumb {
      width: 100%;
      aspect-ratio: 16/10;
      position: relative;
      overflow: hidden;
    }

    .news-card:nth-child(1) .news-card-thumb {
      background: linear-gradient(135deg, #7638FA 0%, #D946EF 100%);
    }
    .news-card:nth-child(2) .news-card-thumb {
      background: linear-gradient(135deg, #F97316 0%, #FBBF24 100%);
    }
    .news-card:nth-child(3) .news-card-thumb {
      background: linear-gradient(135deg, #3B82F6 0%, #06B6D4 100%);
    }
    .news-card:nth-child(4) .news-card-thumb {
      background: linear-gradient(135deg, #10B981 0%, #34D399 100%);
    }

    .news-card-thumb-icon {
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
      width: 48px;
      height: 48px;
      color: rgba(255,255,255,0.3);
    }

    .news-card-body {
      padding: 20px 24px 24px;
    }

    .news-card-tags {
      display: flex;
